":root {
  --ivory: #FFF9F5;
  --blush: #F3D7DF;
  --rose: #D49AA8;
  --sage: #A3AC96;
  --mocha: #554A45;
  --mocha-soft: #6E615B;
  --surface: #FFFFFF;
  --border: #E7CDD4;
  --error-bg: #FDF0F2;
  --error-border: #B24C5C;
  --error-text: #8A2C3B;
  --success-bg: #F2F5EE;
  --success-border: #6F7B5E;
  --shadow: 0 10px 26px rgba(85, 74, 69, 0.08);
  --radius: 16px;
  --radius-sm: 10px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Georgia", "Times New Roman", serif;
  background-color: var(--ivory);
  color: var(--mocha);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

button,
input,
select,
textarea {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--mocha);
}

.sans {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: var(--mocha);
  text-underline-offset: 3px;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--mocha);
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--mocha);
  color: var(--ivory);
  padding: 0.75rem 1.25rem;
  z-index: 100;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-weight: 600;
  border-radius: 0 0 var(--radius-sm) 0;
}

.skip-link:focus {
  left: 0;
}

.container {
  width: min(1120px, 100% - 2rem);
  margin-inline: auto;
}

/* Header & Navigation */
.site-header {
  background-color: var(--surface);
  border-bottom: 2px solid var(--blush);
  position: sticky;
  top: 0;
  z-index: 50;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 0.85rem;
}

